import {supportsSnow} from './plant-snow.js';
import {TUSSOCK_PROFILES} from './tussock-profiles.js';
import {supportsTreeCondition} from './tree-condition.js';
import {stagesForSpecies,supportsProduce,defaultProduce,PRODUCE_COLORS} from './plant-produce.js';
import {supportsSeasons} from './plant-seasons.js';
import {bindPreviewControls} from './flora-preview-controls.js';
import {floraSpecies,validateSpecies} from './flora-species.js';
import {generateSpecies,approveSpecies} from './flora-authoring.js';
import {createFloraPreview} from './flora-preview.js';
import {loadImpostorPackage} from './octahedral-impostor.js';
const $=id=>document.getElementById(id),key='rfl-flora-drafts-v1';let collection=structuredClone(floraSpecies),current,generated,preview,controls,ticket=0;
const say=text=>$('status').textContent=text,fail=e=>say('Error: '+e.message),golden=()=>floraSpecies.some(s=>s.id===current?.id);
const hex=c=>'#'+c.map(x=>Math.round(x*255).toString(16).padStart(2,'0')).join('');
const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255);
function library(){const filter=$('search').value.toLowerCase();$('library').replaceChildren();for(const s of collection.filter(s=>(s.name+' '+s.category).toLowerCase().includes(filter))){const b=document.createElement('button'),small=document.createElement('small');small.textContent=s.category||'CUSTOM';b.append(small,document.createTextNode(s.name.replace('Nauptre · ','')));b.className=s.id===current?.id?'active':'';b.onclick=()=>select(s);$('library').append(b);}}
function settings(){preview.setSettings({yaw:+$('yaw').value,pitch:+$('pitch').value,lod:+$('lod').value,light:+$('light').value,reference:$('reference').value,representation:$('representation').value,leafDither:$('leaf-dither').checked,night:$('light-mode').value==='night'});$('scale-label').hidden=$('reference').value==='none';$('lod-value').textContent=(+$('lod').value).toFixed(2);}
function previewSource(){const recipe={...current.recipe};if(supportsSnow(current))recipe.snowDusting=$('snow-dusting').value;if(supportsTreeCondition(current))recipe.condition=$('plant-condition').value;if(supportsSeasons(current))recipe.season=$('season').value;if(stagesForSpecies(current).length>1)recipe.stage=$('plant-stage').value;if(supportsProduce(current)){recipe.produce=$('produce-kind').value;recipe.produceColor=rgb($('produce-color').value);recipe.produceCount=+$('produce-count').value;recipe.produceScale=+$('produce-size').value;}return {...current,recipe};}
function syncProduce(){const enabled=stagesForSpecies(current).length>1&&!(supportsTreeCondition(current)&&['burnt','stump'].includes($('plant-condition').value));$('plant-stage').disabled=!enabled;for(const id of ['produce-kind','produce-color','produce-count','produce-size']){$(id).disabled=!enabled||!supportsProduce(current)||$('plant-stage').value!=='fruiting';$(id).parentElement.hidden=['shield-fern','tussock','tree-fern','cattail','prototaxite-a','prototaxite-b'].includes(current.recipe.form)||(current.recipe.form==='ginkgo'&&current.recipe.sex==='male');}}
function select(s){current=s;$('snow-dusting').disabled=!supportsSnow(s);$('snow-dusting').value=s.recipe.snowDusting||'none';$('plant-stage').replaceChildren(...stagesForSpecies(s).map(stage=>new Option(({normal:s.recipe.form==='cattail'?'Without heads':'Normal',bud:'Closed bud',flowering:'Flowering',fruiting:s.recipe.form==='tussock'?'Dry seed heads':s.recipe.form==='cattail'?'Brown seed heads':s.recipe.form==='ginkgo'?'Bearing nuts':'Fruiting / cones'})[stage],stage)));$('plant-height').min=s.recipe.form==='shield-fern'?'.3':s.recipe.form==='tussock'?String(TUSSOCK_PROFILES[s.recipe.ecotype].height[0]):s.recipe.form==='tree-fern'?'1':s.recipe.form==='cattail'?'2':s.recipe.form==='mangrove'?'3':s.recipe.form==='zosteophyl'?'.5':s.recipe.form==='calamites'?'1':'.05';$('plant-height').max=s.recipe.form==='shield-fern'?'1.2':s.recipe.form==='tussock'?String(TUSSOCK_PROFILES[s.recipe.ecotype].height[1]):s.recipe.form==='tree-fern'?'15':s.recipe.form==='cattail'?'3':s.recipe.form==='mangrove'?'15':s.recipe.form==='zosteophyl'?'2':s.recipe.form==='calamites'?'20':'200';$('plant-condition-control').hidden=!supportsTreeCondition(s);$('plant-condition').value=s.recipe.condition||'healthy';$('randomize').disabled=!['tree-form','botanical','interiors','xpm-cactus','growth'].includes(s.recipe.kind);$('custom-seed').disabled=$('randomize').disabled;$('botanical-reference').hidden=!s.provenance?.url;$('botanical-description').textContent=s.provenance?.description||'';$('botanical-link').textContent=s.provenance?.source||'';$('botanical-link').href=s.provenance?.url||'#';$('plant-stage').value=s.recipe.stage||(s.recipe.group==='nauptre-cacti'?'flowering':'normal');$('produce-kind').value=s.recipe.produce||defaultProduce(s);$('produce-color').value=hex(s.recipe.produceColor||PRODUCE_COLORS[$('produce-kind').value]);$('produce-count').value=s.recipe.produceCount??12;$('produce-size').value=s.recipe.produceScale??1;syncProduce();$('season').disabled=!supportsSeasons(s);$('season').value=s.recipe.season||'summer';delete current.approval;library();$('name').value=s.name;$('title').textContent=s.name.replace('Nauptre · ','');$('category').textContent=s.category;$('badge').textContent=golden()?(s.recipe.kind==='interiors'?'INTERIORS REFERENCE':['tree-form','botanical','xpm-cactus'].includes(s.recipe.kind)?'PLANT FORM':'GOLDEN REFERENCE'):'DRAFT / UNAPPROVED';$('fields').disabled=golden();$('name').disabled=golden();$('seed').replaceChildren();for(const seed of s.seeds){const o=document.createElement('option');o.value=seed;o.textContent=seed;$('seed').append(o);}$('growth').hidden=s.recipe.kind!=='growth';$('domain').value=s.rendering.sampling;$('biomes').value=s.ecology.biomes.join(', ');for(const k of ['bark','leaf','flower']){$(k).value=hex(s.palette[k]);$(k).disabled=!['growth','tree-form','botanical','xpm-cactus'].includes(s.recipe.kind);}for(const k of ['depth','forks','spread','foliage','flowers'])$(k).value=s.recipe[k]??({depth:2,forks:3,spread:.6,foliage:1,flowers:0}[k]);$('custom-seed').value=s.seeds[0];$('representation').value='mesh';rebuild();}
function rebuild(){try{generated=generateSpecies(previewSource(),+$('seed').value);preview.setCapture(null);++ticket;preview.setMesh(generated.mesh);$('plant-height').value=(generated.mesh.frameDiagnostics?.dimensions[1]||generated.height).toFixed(3);$('height').textContent=generated.height.toFixed(2);$('triangles').textContent=generated.diagnostics.triangles;$('variants').textContent=current.seeds.length;$('sampling').textContent=current.rendering.sampling==='sphere'?'360°':'HEMI';$('view-label').textContent=golden()?'REFERENCE FORM':'DRAFT FORM';settings();say(golden()?'Reference preset. Duplicate to edit; the original remains unchanged.':'Draft generated. Inspect every variant and angle before approval.');}catch(e){fail(e);}}
function edit(){if(golden())return;try{current.name=$('name').value;current.rendering.sampling=$('domain').value;current.ecology.biomes=$('biomes').value.split(',').map(s=>s.trim()).filter(Boolean);if(current.recipe.kind==='growth'){current.recipe.height=+$('plant-height').value;for(const k of ['depth','forks','spread','foliage','flowers'])current.recipe[k]=+$(k).value;for(const k of ['bark','leaf','flower'])current.palette[k]=rgb($(k).value);const seed=+$('custom-seed').value;current.seeds=[seed];$('seed').replaceChildren(new Option(String(seed),String(seed)));}else {current.recipe.heightMeters=+$('plant-height').value;if(['tree-form','botanical','xpm-cactus'].includes(current.recipe.kind))for(const k of ['bark','leaf','flower'])current.palette[k]=rgb($(k).value);}delete current.approval;$('badge').textContent='DRAFT / UNAPPROVED';$('title').textContent=current.name;$('representation').value='mesh';rebuild();library();}catch(e){fail(e);}}
function uniqueID(base){let id=base,i=1;while(collection.some(s=>s.id===id))id=base+'-'+i++;return id;}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
try{preview=createFloraPreview($('canvas'));controls=bindPreviewControls($('canvas'),{frameInterval:preview.mode==='software'?100:0,onChange(state){for(const id of ['yaw','pitch','lod'])$(id).value=state[id];try{settings();}catch(e){$('auto-orbit').checked=false;controls.update({autoOrbit:false});fail(e);}}});$('auto-orbit').onchange=()=>controls.update({autoOrbit:$('auto-orbit').checked});try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))for(const s of saved){validateSpecies(s);if(!collection.some(x=>x.id===s.id))collection.push(s);}}catch{say('Some local drafts could not be loaded; import your exported backup.');}
 for(const id of ['plant-condition','plant-stage','produce-kind','produce-color','produce-count','produce-size'])$(id).onchange=()=>{if(id==='produce-kind')$('produce-color').value=hex(PRODUCE_COLORS[$('produce-kind').value]);syncProduce();$('representation').value='mesh';rebuild();};
 $('snow-dusting').onchange=()=>{$('representation').value='mesh';rebuild();};
 $('season').onchange=()=>{$('representation').value='mesh';rebuild();};$('search').oninput=library;$('seed').onchange=()=>{$('representation').value='mesh';rebuild();};
 $('custom-seed').onchange=()=>{if(golden())return;try{const seed=Number($('custom-seed').value),candidate={...current,seeds:[seed]};validateSpecies(candidate);current.recipe=previewSource().recipe;current.seeds=[seed];delete current.approval;select(current);}catch(e){$('custom-seed').value=current.seeds[0];fail(e);}};
 $('randomize').onclick=()=>{try{const s=structuredClone(previewSource()),seed=crypto.getRandomValues(new Uint32Array(1))[0];if(golden()){s.id=uniqueID(current.id+'-variant');s.name=current.name+' variant';s.version=1;s.provenance={...s.provenance,kind:'derived',sourceSpecies:current.id};collection.push(s);}else collection[collection.indexOf(current)]=s;s.seeds=[seed];delete s.approval;select(s);say('Random variant '+seed+'. Save the draft or export to keep this exact form.');}catch(e){fail(e);}};
 $('duplicate').onclick=()=>{const s=structuredClone(previewSource());s.id=uniqueID(current.id+'-copy');s.name=current.name+' copy';s.version=1;s.provenance={...s.provenance,kind:'derived',sourceSpecies:current.id,sourceVersion:current.version};delete s.approval;collection.push(s);select(s);};
 $('new').onclick=()=>{const s={...structuredClone(floraSpecies.find(s=>s.id==='nauptre-joshua')),id:uniqueID('new-tree'),name:'Untitled branching tree',version:1,seeds:[42],recipe:{kind:'growth',height:4,depth:2,forks:3,spread:.6,foliage:1,flowers:0},provenance:{kind:'procedural'},ecology:{biomes:['woodland'],aquatic:false,weight:1,maxSlope:.6}};collection.push(s);select(s);};
 for(const id of ['name','plant-height','depth','forks','spread','foliage','flowers','bark','leaf','flower','domain','biomes'])$(id).onchange=edit;
 for(const id of ['yaw','pitch','lod'])$(id).oninput=()=>controls.update({[id]:+$(id).value});
 for(const id of ['light','reference','leaf-dither','light-mode'])$(id).oninput=()=>{try{settings();}catch(e){fail(e);}};
 $('representation').onchange=async()=>{const serial=++ticket;try{if($('representation').value==='impostor'){if(!golden()||current.recipe.kind!=='nauptre-golden'||supportsProduce(current)){ $('representation').value='mesh';settings();say('This species has no baked package. Approve/export and run the offline baker.');return;}say('Loading approved offline captures…');const index=await fetch('./baked/impostors/index.json').then(r=>{if(!r.ok)throw Error('Missing capture index');return r.json();}),entry=index.models.find(m=>m.id===generated.id);if(!entry)throw Error('No capture for selected variant');const p=await loadImpostorPackage(new URL('./baked/impostors/'+entry.url,location.href),entry.meshHash);if(serial!==ticket)return;const scale=generated.conversion?.multiplier||1;preview.setCapture({...p,center:p.center.map(x=>x*scale),radius:p.radius*scale});say('Existing baseline bake: '+(p.sampling||'sphere')+' / '+p.grid+' × '+p.grid+' views. New exports use the species capture-domain setting.');}else if($('representation').value==='community')say('Seeded arrangement study of this species. Planetary ecology integration is a later milestone.');settings();}catch(e){$('representation').value='mesh';settings();fail(e);}};
 $('save').onclick=()=>{try{if(!golden())current.recipe=previewSource().recipe;for(const s of collection)validateSpecies(s);localStorage.setItem(key,JSON.stringify(collection.filter(s=>!floraSpecies.some(g=>g.id===s.id))));say('Drafts saved in this browser. Export JSON to keep a portable copy.');}catch(e){fail(e);}};
 $('approve').onclick=async()=>{const s=structuredClone(previewSource()),serial=ticket;try{$('approve').disabled=true;const approved=await approveSpecies(s);if(serial!==ticket){say('Definition changed during approval. Review and approve again.');return;}download(approved,approved.id+'-approved.json');$('badge').textContent='APPROVED / EXPORTED';say('Approved '+approved.seeds.length+' variant(s). Exported source includes a content-bound approval; offline baking is the next step.');}catch(e){fail(e);}finally{$('approve').disabled=false;}};
 $('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const file=$('file').files[0];if(!file)return;if(file.size>25*1024*1024)throw Error('Import limit is 25 MB');let s=JSON.parse(await file.text());if(s.vertices){if(s.units!=='m')throw Error('Imported mesh must explicitly declare units: m');s={...structuredClone(floraSpecies.find(s=>s.id==='nauptre-bushes')),id:s.id||'imported-plant',name:s.name||'Imported plant',seeds:[0],recipe:{kind:'imported',vertices:s.vertices},provenance:{kind:'imported',filename:file.name}};}validateSpecies(s);s.id=uniqueID(s.id);delete s.approval;for(const seed of s.seeds)generateSpecies(s,seed);collection.push(s);select(s);}catch(e){fail(e);}finally{$('file').value='';}};
 new ResizeObserver(()=>{try{preview.draw();}catch(e){fail(e);}}).observe($('canvas'));select(collection.find(s=>s.id==='tree-acacia'));
}catch(e){fail(e);}
